    render: function(iconName, size = 18, className = '') {
        const svg = this.icons[iconName] || this.icons['code'];
        return svg.replace('<svg', `<svg width="${size}" height="${size}" class="${className}"`);
    },

    init: function() {
        document.querySelectorAll('[data-lucide]').forEach(el => {
            const name = el.getAttribute('data-lucide');
            const size = el.getAttribute('data-size') || 18;
            el.innerHTML = this.render(name, size);
        });
    }
